// 模拟一组订单数据（实际项目中通常来自接口返回）
const orders = [
  { id: 1, product: '键盘',   price: 299,  quantity: 2 },
  { id: 2, product: '鼠标',   price: 99,   quantity: 3 },
  { id: 3, product: '显示器', price: 1299, quantity: 1 },
  { id: 4, product: '耳机',   price: 199,  quantity: 4 },
];

// 1. map：把每条订单映射成一段展示文案（生成等长的新数组）
const descriptions = orders.map((order) => `${order.product} x${order.quantity}`);
console.log(descriptions);
// [ '键盘 x2', '鼠标 x3', '显示器 x1', '耳机 x4' ]

// 2. filter：挑出单价超过 100 元的订单
const expensive = orders.filter((order) => order.price > 100);
console.log(expensive.length); // 3

// 3. 链式组合：先筛选贵重商品，再算出每单的小计（price * quantity）
const expensiveTotals = orders
  .filter((order) => order.price > 100)
  .map((order) => order.price * order.quantity);
console.log(expensiveTotals); // [ 598, 1299, 796 ]

// 4. reduce：把所有订单汇总成一个总金额
const totalAmount = orders.reduce(
  (sum, order) => sum + order.price * order.quantity,
  0 // 累加器初始值，务必显式书写
);
console.log(totalAmount); // 2990

// 5. reduce 也能做统计：计算所有商品的总件数
const totalQuantity = orders.reduce((sum, order) => sum + order.quantity, 0);
console.log(totalQuantity); // 10

// 验证：原数组没有被修改（map/filter/reduce 都是非破坏性的）
console.log(orders.length); // 4

